-- Rollback for 20261102100000_p2_staff_profile_and_huddle.sql.
-- REFUSES while any designation, address, colour, must_change_password flag, solution_by or solved_by value exists: dropping the
-- columns would destroy them. Export first:
--   select id, designation, address, task_color, must_change_password from profiles where designation is not null or address is not null or must_change_password;
--   select id, solution_by, solved_by from meeting_issues where solution_by is not null or solved_by is not null;
-- then null them deliberately. (task_color is regenerated by the migration, so it does not block the rollback.)
begin;
do $g$
begin
  if exists (select 1 from public.profiles where designation is not null or address is not null or must_change_password) then
    raise exception 'rollback refused: profiles has designation / address / must_change_password values (export, then clear deliberately)';
  end if;
  if exists (select 1 from public.meeting_issues where solution_by is not null or solved_by is not null) then
    raise exception 'rollback refused: meeting_issues has solution_by / solved_by values (export, then clear deliberately)';
  end if;
end $g$;

drop function if exists public.propose_huddle_solution(uuid, text);
drop function if exists public.raise_huddle_issue(text);
drop trigger if exists meeting_issues_notify on public.meeting_issues;
drop function if exists public._trg_meeting_issue_notify();
drop trigger if exists meeting_issues_stamp on public.meeting_issues;
drop function if exists public._trg_meeting_issue_stamp();
alter table public.meeting_issues drop column if exists solution_by, drop column if exists solved_by;

drop trigger if exists zy_profile_assign_color on public.profiles;
drop function if exists public._trg_profile_assign_color();
drop function if exists public._hsl_hex(numeric, numeric, numeric);
drop function if exists public.complete_forced_password_change();
drop trigger if exists zz_profile_password_marker on public.profiles;
drop function if exists public._trg_profile_password_marker();
drop trigger if exists guard_profile_staff_fields on public.profiles;
drop function if exists public.guard_profile_staff_fields();
alter table public.profiles
  drop column if exists designation, drop column if exists address, drop column if exists must_change_password,
  drop column if exists password_marker, drop column if exists task_color;

notify pgrst, 'reload schema';
commit;
